using System;using System.Linq;using System.Diagnostics;using System.Threading;using System.Text;using System.IO;using System.Runtime.Serialization.Json;using System.Windows;using System.Windows.Automation;
namespace GlassBoard {
    public static class NeteaseTimelineRules {
        public static bool Time(string text,out double seconds){seconds=0;var p=text.Trim().Split(':');if(p.Length<2||p.Length>3)return false;int[] v=new int[p.Length];for(int i=0;i<p.Length;i++)if(!int.TryParse(p[i],out v[i])||v[i]<0)return false;if(v[p.Length-1]>59||(p.Length==3&&v[1]>59))return false;seconds=p.Length==3?v[0]*3600.0+v[1]*60+v[2]:v[0]*60.0+v[1];return seconds<=359999;}
        public static bool Progress(string text,out double current,out double total){current=total=0;if(string.IsNullOrWhiteSpace(text))return false;string clean=text.Normalize(NormalizationForm.FormKC).Replace(" ","");var parts=clean.Split(new[]{'/','|'});return parts.Length==2&&Time(parts[0],out current)&&Time(parts[1],out total)&&total>0&&current<=total;}
        public static bool Source(string source){return (source??"").IndexOf("cloudmusic",StringComparison.OrdinalIgnoreCase)>=0;}
        public static bool WindowTitle(string name,string track){return !string.IsNullOrWhiteSpace(track)&&!string.IsNullOrWhiteSpace(name)&&name.IndexOf("MediaPlayer",StringComparison.OrdinalIgnoreCase)<0&&(name.Trim().Equals(track.Trim(),StringComparison.OrdinalIgnoreCase)||new[]{" - "," – "," — "}.Any(separator=>name.Trim().StartsWith(track.Trim()+separator,StringComparison.OrdinalIgnoreCase)));}
        public static double RangeTarget(double seconds,double duration,double min,double max){if(duration<=0||max<=min||double.IsNaN(seconds)||double.IsInfinity(seconds))throw new ArgumentException("Invalid playback range");return min+Math.Max(0,Math.Min(1,seconds/duration))*(max-min);}
    }
    // Independent UI Automation adapter, inspired by the documented progress-text
    // approach in Widdit/now-playing-service. No player injection or file access.
    public sealed class NeteaseUiReader {
        AutomationElement window,progress;string key="",vendorKey="";DateTime changedAt=DateTime.MinValue,lastAdvance=DateTime.MinValue;double previous=-1;RangeValuePattern seekRange;DateTime lastRangeScan=DateTime.MinValue;
        AutomationElement FindWindow(MediaRequest r){foreach(var process in Process.GetProcessesByName("cloudmusic")){try{var windows=AutomationElement.RootElement.FindAll(TreeScope.Children,new PropertyCondition(AutomationElement.ProcessIdProperty,process.Id));foreach(AutomationElement candidate in windows)if(NeteaseTimelineRules.WindowTitle(candidate.Current.Name,r.Title))return candidate;}catch{}finally{process.Dispose();}}return null;}
        bool ReadText(AutomationElement element,out double current,out double total){current=total=0;try{return element!=null&&NeteaseTimelineRules.Progress(element.Current.Name,out current,out total);}catch{return false;}}
        AutomationElement FindProgress(out double current,out double total){current=total=0;var texts=window.FindAll(TreeScope.Descendants,new PropertyCondition(AutomationElement.ControlTypeProperty,ControlType.Text));foreach(AutomationElement text in texts)if(ReadText(text,out current,out total))return text;return null;}
        RangeValuePattern FindSeekRange(){if(window==null||progress==null)return null;if(seekRange!=null){try{if(!seekRange.Current.IsReadOnly&&seekRange.Current.Maximum>seekRange.Current.Minimum)return seekRange;}catch{}seekRange=null;}if((DateTime.UtcNow-lastRangeScan).TotalSeconds<3)return null;lastRangeScan=DateTime.UtcNow;Rect text;try{text=progress.Current.BoundingRectangle;}catch{return null;}var sliders=window.FindAll(TreeScope.Descendants,new PropertyCondition(AutomationElement.IsRangeValuePatternAvailableProperty,true));RangeValuePattern best=null;double score=0;foreach(AutomationElement slider in sliders){try{string name=slider.Current.Name??"";if(name.IndexOf("音量",StringComparison.OrdinalIgnoreCase)>=0||name.IndexOf("volume",StringComparison.OrdinalIgnoreCase)>=0)continue;object value;if(!slider.TryGetCurrentPattern(RangeValuePattern.Pattern,out value))continue;var range=(RangeValuePattern)value;if(range.Current.IsReadOnly||range.Current.Maximum<=range.Current.Minimum)continue;Rect rect=slider.Current.BoundingRectangle;bool explicitName=name.IndexOf("进度",StringComparison.OrdinalIgnoreCase)>=0||name.IndexOf("progress",StringComparison.OrdinalIgnoreCase)>=0||name.IndexOf("seek",StringComparison.OrdinalIgnoreCase)>=0;if(!explicitName&&(rect.IsEmpty||text.IsEmpty||rect.Width<200||Math.Abs(rect.Top-text.Top)>65))continue;double rank=(explicitName?100000:0)+rect.Width;if(rank>score){best=range;score=rank;}}catch{}}seekRange=best;return best;}
        public MediaSnapshot Read(MediaRequest r){var result=new MediaSnapshot{Key=r.Key,Source=r.Source,Backend="Netease UIA",Status="未找到网易云进度文本；请显示主窗口并将鼠标移到播放器进度条",TimelineStatus="未找到进度文本"};if(!NeteaseTimelineRules.Source(r.Source))return result;if(r.Key!=vendorKey){NeteaseMusicHelper.SetTrack(null);vendorKey=r.Key;}NeteaseMusicHelper.SetTrack(r.Title);NeteaseMusicHelper.SetPlaying(r.Playing);int vendorPosition,vendorDuration;if(r.Command!="seek"&&NeteaseMusicHelper.TryGetCachedProgress(out vendorPosition,out vendorDuration)){result.Available=true;result.Position=vendorPosition;result.Duration=vendorDuration;result.MaxSeek=vendorDuration;result.Rate=0;result.CanSeek=false;result.Status="OK";result.TimelineStatus="Now Playing COM UIA；真实进度（只读）";return result;}if(r.Key!=key){key=r.Key;progress=null;seekRange=null;lastRangeScan=DateTime.MinValue;previous=-1;changedAt=DateTime.UtcNow;lastAdvance=DateTime.UtcNow;}if((DateTime.UtcNow-changedAt).TotalMilliseconds<700){result.Status="等待切歌后的界面更新";return result;}try{if(window!=null&&!NeteaseTimelineRules.WindowTitle(window.Current.Name,r.Title))window=null;}catch{window=null;}if(window==null){window=FindWindow(r);progress=null;seekRange=null;lastRangeScan=DateTime.MinValue;}if(window==null){result.Status="请打开网易云主窗口，并保持播放进度可见";return result;}double current,total;if(!ReadText(progress,out current,out total)){progress=FindProgress(out current,out total);if(progress==null){result.Status="Now Playing 尚未读到进度；"+(string.IsNullOrEmpty(NeteaseMusicHelper.LastError)?"请显示网易云主窗口进度条":NeteaseMusicHelper.LastError);return result;}}if(current!=previous){previous=current;lastAdvance=DateTime.UtcNow;}else if(r.Playing&&(DateTime.UtcNow-lastAdvance).TotalSeconds>4){progress=null;result.Status="进度文本未更新，请显示网易云窗口的进度条";return result;}var range=FindSeekRange();result.Available=true;result.Status="OK";result.Duration=total;result.Position=current;result.MinSeek=0;result.MaxSeek=total;result.Rate=0;result.CanSeek=range!=null;result.TimelineStatus=range!=null?"UI Automation progress and writable range":"UI Automation progress; read-only";if(r.Command=="seek"){if(range==null){result.Status="播放器未开放可写进度控件";return result;}range.SetValue(NeteaseTimelineRules.RangeTarget(r.Seconds,total,range.Current.Minimum,range.Current.Maximum));result.Position=Math.Max(0,Math.Min(total,r.Seconds));previous=-1;lastAdvance=DateTime.UtcNow;}return result;}
        public static int Run(){int code=0;var thread=new Thread(()=>{try{var reader=new NeteaseUiReader();using(var input=new StreamReader(Console.OpenStandardInput(),new UTF8Encoding(false,true),true,4096))using(var output=Console.OpenStandardOutput()){MediaWireProtocol.Loop(input,output,reader.Read);}}catch(Exception ex){code=1;try{using(var error=new StreamWriter(Console.OpenStandardError(),new UTF8Encoding(false))){error.WriteLine(ex.GetType().Name+"："+ex.Message);}}catch{}}});thread.SetApartmentState(ApartmentState.MTA);thread.Start();thread.Join();return code;}
    }
}
